// Mic fidelity value — record JAH-GPCS-USBMIC-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"sample_rate_khz": 96, "bit_depth": 24, "price_usd": 150};
var value = (m.sample_rate_khz*m.bit_depth/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-USBMIC-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-USBMIC-000001|' + value.toFixed(2) + ' fidelity value');

